from qiskit import QuantumCircuit
from qiskit.quantum_info import Statevector

# MUST mirror data/figures/s1-q063/generate.py (the drawn circuit).
STEM = [("x", 1), ("h", 1), ("h", 0), ("cx", 0, 1), ("h", 0), ("h", 1)]


def build(gates):
    qc = QuantumCircuit(2)
    for name, *args in gates:
        getattr(qc, name)(*args)
    return qc


def probs(qc):
    return {str(k): round(float(v), 6)
            for k, v in Statevector(qc).probabilities_dict().items() if float(v) > 1e-9}


got = probs(build(STEM))
claims = {
    "A": {"11": 1.0},
    "B": {"10": 1.0},
    "C": {"01": 1.0},
    "D": {"01": 0.5, "10": 0.5},
}
proven, evidence = [], {}
for k, c in claims.items():
    m = got == c
    evidence[k] = f"executed Statevector(drawn circuit).probabilities_dict() -> {got}; option {k} claims {c} -> match={m}"
    if m:
        proven.append(k)

# The misconceptions, executed:
no_cx = probs(build([g for g in STEM if g[0] != "cx"]))
evidence["B"] += f"  (that is the circuit WITHOUT the CNOT: {no_cx} — with the target in |->, the CNOT kicks a phase back onto q0)"
evidence["C"] += f"  (the no-kickback result read q0-first: {sorted(k[::-1] for k in no_cx)}; the real q0 outcome is 1, the last character)"
evidence["D"] += f"  (no entanglement survives: the executed state is the product basis state {sorted(got)})"
emit_verdict({"answer": proven, "evidence": evidence,
              "observed": {"probabilities": got, "without_cx": no_cx}})
